npc {
  map = "prontera", x = 275, y = 355, dir = 3, sprite = 79, name = "Nun",
  src = "817:jobs/priest.txt:407",
  on_click = function()
    local c
    if v.job_priest_q == 3 then goto questexamdone end
    if v.job_priest_q == 2 then goto questexam end
    mes "[Nun]"
    mes "Countless heros rest here, I just tend to the cleanliness of their tombstones."
    close()
    do return end
    ::questexam::
    mes "[Nun]"
    mes(("You are ^0000FF" .. char_info(0)) .. "^000000, correct? I hope you're ready for the Quest.")
    next()
    mes "[Nun]"
    mes "Are you prepared?"
    next()
    c = menu("Yes.", "No.")
    if c == 1 then goto yes elseif c == 2 then goto no end
    ::questexamdone::
    mes "[Nun]"
    mes(("Congratulations ^0000FF" .. char_info(0)) .. "^000000 on passing the Quest!")
    close()
    do return end
    ::yes::
    mes "[Nun]"
    mes "Best of luck!"
    next()
    warp("job_priest", 100, 17)
    close()
    do return end
    ::no::
    mes "[Nun]"
    mes "I understand, continue preparing then."
    close()
  end,
}

